import{_ as l,H as i,f as e,i as t}from"./chunks/framework.Cvt1eIE0.js";const O=JSON.parse('{"title":"VO 和 VIO","description":"","frontmatter":{},"headers":[],"relativePath":"notes/大创-无人机与自主导航/02-VO和VIO.md","filePath":"notes/大创-无人机与自主导航/02-VO和VIO.md"}'),o={name:"notes/大创-无人机与自主导航/02-VO和VIO.md"};function r(n,a,s,p,d,h){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="vo-和-vio" tabindex="-1">VO 和 VIO <a class="header-anchor" href="#vo-和-vio" aria-label="Permalink to &quot;VO 和 VIO&quot;">​</a></h1><h2 id="vo" tabindex="-1">VO <a class="header-anchor" href="#vo" aria-label="Permalink to &quot;VO&quot;">​</a></h2><p>视觉里程计（Visual Odometry，简称VO）是利用<strong>连续图像序列</strong> 估计 相机自身运动（位姿变化）的一种技术。</p><p>它的作用是拿到相机的相对位姿变化(平移和旋转)</p><p>与IMU和激光雷达相比，成本更低，但受限于光照和场景特征等因素。</p><h3 id="基本原理" tabindex="-1">基本原理 <a class="header-anchor" href="#基本原理" aria-label="Permalink to &quot;基本原理&quot;">​</a></h3><ol><li><p>**特征匹配：**就是找出图片中的同一个物体。从连续帧中提取图像特征点，并在相邻帧之间进行匹配。然后跟踪这个特征点。</p></li><li><p>**几何约束与位姿解算：**利用特征点在不同时间(帧)下在画面里的位置，通过几何约束（如本质矩阵、基础矩阵或相机模型）解算摄像头的相对位姿变化。</p></li></ol><p>举个例子：如果你的相机搭载在一台无人机上，而无人机在只有雪白的墙壁的室内飞，那么摄像机拍到的画面都是白花花一片，或者墙壁的纹理是整齐的，重复的，相机拍到的不同画面长得几乎一模一样——这个时候根本没有特征点，无法解算，我们称之为<strong>低纹理环境</strong>。但如果墙上有标记，比如一颗钉子，那么就能以钉子为特征点，用数学解算相机的位姿变化。</p><h3 id="模块和步骤" tabindex="-1">模块和步骤 <a class="header-anchor" href="#模块和步骤" aria-label="Permalink to &quot;模块和步骤&quot;">​</a></h3><ul><li>图像采集和预处理模块</li><li>特征提取描述模块</li><li>特征匹配跟踪模块</li><li>运动解算模块</li><li>优化与滤波</li></ul><ol><li>使用相机获得连续的图像序列</li><li>预处理，滤波去噪，转为灰度图等操作</li><li>特征点检测如Harris角点、FAST、SIFT、SURF等方法，在图像中检测高辨识度的特征点，当然也有论文研究特征线——PL VIO</li><li>为每个特征点生成描述子(SIFT、SURF、ORB等)</li><li>特征匹配，跟踪(Brute-Force,FLANN，Lucas-Kanade等)</li><li>运动解算</li><li>优化(最小二乘，Bundle Adjustment)和滤波(卡尔曼滤波EKF等)</li></ol><h3 id="限制和不足" tabindex="-1">限制和不足 <a class="header-anchor" href="#限制和不足" aria-label="Permalink to &quot;限制和不足&quot;">​</a></h3><ul><li><p>相机的输出频率有限，一般不超过100Hz；</p></li><li><p>在基于单目的VO系统中，不能精准估计尺度信息</p></li><li><p>不适合低纹理（如白墙）</p></li><li><p>不适合高速运动或者高动态的场景（出现曝光过度或者不足）</p></li></ul><h2 id="vio" tabindex="-1">VIO <a class="header-anchor" href="#vio" aria-label="Permalink to &quot;VIO&quot;">​</a></h2><p>视觉惯性里程计(Visual-Inertial Odometry，VIO)，是一个使用一个或者多个相机、一个或者多个IMU进行传感器状态测量的技术(也就是解算位姿)</p><p>相机和IMU相比于其他传感器比较廉价，也比较轻便，因此在现代无人机上普遍配备了VIO</p><p>前面已经讲解了VO和IMU，而VIO设计理念就在于，将相机和IMU两种的传感器进行数据融合，达到“优势互补”。</p><ul><li>IMU弥补输VO出频率不高和过渡依赖光照和速度限制的不足</li><li>VO弥补IMU存在漂移误差的不足</li></ul>',18)])])}const u=l(o,[["render",r]]);export{O as __pageData,u as default};
